def get_v_p(n, p):
    count = 0
    while n % p == 0:
        count += 1
        n //= p
    return count

def find_p():
    for p in range(2, 100000):
        if p > 1:
            a = get_v_p(39455, p)
            b = get_v_p(94175, p)
            if b == 2 * a and a > 0:
                print(f"p={p}, a={a}, b={b}")

find_p()

